// routes/upload.js - FastAPI文件上传模块
const { Router } = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs');

const router = Router();
const upload = multer({ storage: multer.memoryStorage() });

// 业务白名单：仅允许上传到用户专属目录
const USER_DIR = '/data/uploads';

// 辅助函数：清理文件名中的恶意字符
function sanitizeFilename(filename) {
  // 防御1: 移除路径分隔符
  let cleaned = filename.replace(/[\/\\]/g, '');
  // 防御2: 移除空字节
  cleaned = cleaned.replace(/\0/g, '');
  return cleaned;
}

// 辅助函数：检查路径是否在允许的目录内
function isPathSafe(targetPath) {
  // 防御3: 使用startswith检查前缀
  return targetPath.startsWith(USER_DIR + '/');
}

router.post('/upload', upload.single('file'), (req, res) => {
  const userId = req.body.userId || 'default';
  const originalName = req.file.originalname;

  // 业务逻辑：用户目录 + 清理后的文件名
  const userDir = path.join(USER_DIR, userId);
  const safeName = sanitizeFilename(originalName);
  const finalPath = path.join(userDir, safeName);

  // 关键检查：确保最终路径在允许范围内
  if (!isPathSafe(finalPath)) {
    return res.status(400).json({ error: '非法路径' });
  }

  // 确保用户目录存在
  if (!fs.existsSync(userDir)) {
    fs.mkdirSync(userDir, { recursive: true });
  }

  // 写入上传文件
  fs.writeFileSync(finalPath, req.file.buffer);
  res.json({ status: 'ok', path: finalPath });
});

// 下载接口
router.get('/download', (req, res) => {
  const { userId, filename } = req.query;
  const safeName = sanitizeFilename(filename);
  const finalPath = path.join(USER_DIR, userId, safeName);

  if (!isPathSafe(finalPath)) {
    return res.status(400).json({ error: '非法路径' });
  }

  if (fs.existsSync(finalPath)) {
    res.sendFile(finalPath);
  } else {
    res.status(404).json({ error: '文件不存在' });
  }
});

module.exports = router;

