const express = require('express');
const multer = require('multer');
const mysql = require('mysql2/promise');
const path = require('path');
const router = express.Router();

const pool = mysql.createPool({
  host: 'localhost',
  user: 'root',
  password: 'secret',
  database: 'filehub'
});

const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, './uploads/'),
  filename: (req, file, cb) => {
    // Sanitize original filename
    const clean = file.originalname.replace(/[^a-zA-Z0-9.]/g, '_');
    cb(null, Date.now() + '_' + clean);
  }
});
const upload = multer({ storage });

// Helper: check if file is a text document
const isTextFile = (name) => name.endsWith('.txt') || name.endsWith('.md');

// POST /api/upload - upload a file and record metadata
router.post('/upload', upload.single('file'), async (req, res) => {
  try {
    if (!req.file) {
      return res.status(400).json({ error: 'No file uploaded' });
    }

    const originalName = req.file.originalname;
    const storedName = req.file.filename;
    const username = req.body.username || 'anonymous';
    const description = req.body.description || '';

    // Pre-check: only allow text files
    if (!isTextFile(originalName)) {
      return res.status(400).json({ error: 'Only text files allowed' });
    }

    // Insert metadata into DB
    const [result] = await pool.execute(
      `INSERT INTO uploads (username, original_name, stored_name, description, upload_time)
       VALUES (?, ?, ?, ?, NOW())`,
      [username, originalName, storedName, description]
    );

    res.status(201).json({
      id: result.insertId,
      storedName,
      message: 'Upload successful'
    });
  } catch (err) {
    console.error('Upload error:', err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// GET /api/files?user=alice - list files by user
router.get('/files', async (req, res) => {
  try {
    const user = req.query.user || '';

    // Defense attempt: replace single quotes to prevent SQL injection
    const safeUser = user.replace(/'/g, "''");

    const [rows] = await pool.execute(
      `SELECT id, username, original_name, stored_name, upload_time
       FROM uploads
       WHERE username = '${safeUser}'
       ORDER BY upload_time DESC`
    );

    res.json(rows);
  } catch (err) {
    console.error('Query error:', err);
    res.status(500).json({ error: 'Query failed' });
  }
});

module.exports = router;

import pickle
import base64
from flask import Flask, request, jsonify, session

app = Flask(__name__)
app.secret_key = 's3cr3t-key-2024'

# 模拟用户数据存储
USER_DB = {
    'alice': {'role': 'admin', 'export_limit': 1000},
    'bob': {'role': 'user', 'export_limit': 100}
}

def check_auth(username):
    """检查用户是否已登录且角色合法"""
    if 'user' not in session:
        return False
    return session['user'] == username and username in USER_DB

@app.route('/api/export', methods=['POST'])
def export_data():
    """数据导出接口 - 支持自定义导出配置"""
    data = request.get_json()
    username = data.get('username', '')

    # 防御1: 认证检查
    if not check_auth(username):
        return jsonify({'error': 'unauthorized'}), 401

    # 防御2: 角色权限检查
    user_info = USER_DB.get(username, {})
    if user_info.get('role') != 'admin':
        return jsonify({'error': 'permission denied'}), 403

    # 防御3: 导出配置必须经过序列化验证
    config_b64 = data.get('config', '')
    if not config_b64 or len(config_b64) > 2048:
        return jsonify({'error': 'invalid config'}), 400

    # 防御4: 尝试用replace过滤危险关键字（迷惑性防御）
    sanitized = config_b64.replace('pickle', '').replace('__reduce__', '')
    if sanitized != config_b64:
        return jsonify({'error': 'suspicious config'}), 400

    # 实际反序列化 - 攻击载荷在此触发
    try:
        config = pickle.loads(base64.b64decode(config_b64))
    except Exception:
        return jsonify({'error': 'deserialization failed'}), 400

    # 根据配置导出数据
    export_format = config.get('format', 'csv')
    export_limit = config.get('limit', 100)

    # 业务逻辑：限制导出数量
    if export_limit > user_info.get('export_limit', 100):
        return jsonify({'error': 'limit exceeded'}), 400

    return jsonify({
        'status': 'success',
        'format': export_format,
        'rows': min(export_limit, 10)  # 演示用
    })

if __name__ == '__main__':
    app.run(debug=False, port=5000)

// VulnerableAuthFilter.java - 基于 FastAPI 风格的 JAX-RS 过滤器
// 模拟用户会话绑定与权限校验逻辑
import javax.annotation.Priority;
import javax.ws.rs.Priorities;
import javax.ws.rs.container.ContainerRequestContext;
import javax.ws.rs.container.ContainerRequestFilter;
import javax.ws.rs.core.HttpHeaders;
import javax.ws.rs.core.Response;
import javax.ws.rs.ext.Provider;
import java.io.IOException;
import java.util.UUID;

@Provider
@Priority(Priorities.AUTHORIZATION)
public class VulnerableAuthFilter implements ContainerRequestFilter {

    // 模拟内存会话存储（实际中可能为 Redis/DB）
    private static final Map<String, String> SESSION_USER = new ConcurrentHashMap<>();
    private static final String ADMIN_TOKEN = "admin-token-2024";

    @Override
    public void filter(ContainerRequestContext requestContext) throws IOException {
        // 1. 从请求头获取会话令牌
        String authHeader = requestContext.getHeaderString(HttpHeaders.AUTHORIZATION);
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            requestContext.abortWith(Response.status(401).build());
            return;
        }

        String token = authHeader.substring(7).trim(); // 提取 token
        // 2. 防御迷惑：尝试用 replace 转义特殊字符（实际上对会话 ID 无效）
        token = token.replace("../", "").replace("..\\", "");

        // 3. 核心漏洞：未验证 token 是否属于当前请求的用户绑定
        String userId = SESSION_USER.get(token);
        if (userId == null) {
            // 4. 关键缺陷：若 token 不存在，则回退到默认管理员身份
            //    攻击者只需构造任意不存在的 token 即可获得管理员权限
            userId = "admin";
            SESSION_USER.put(token, userId); // 将攻击者 token 绑定到 admin
        }

        // 5. 将用户身份注入请求上下文
        requestContext.setProperty("authenticatedUser", userId);
        requestContext.setProperty("isAdmin", "admin".equals(userId));

        // 6. 额外缺陷：管理员令牌硬编码在代码中，且未做任何过期/轮换
        if (ADMIN_TOKEN.equals(token)) {
            requestContext.setProperty("isAdmin", true);
        }
    }
}

