import json
from django.http import JsonResponse
from django.views.decorators.http import require_http_methods
from django.contrib.auth.decorators import login_required
from django.core.validators import validate_email
from django.core.exceptions import ValidationError
from pymongo import MongoClient

client = MongoClient('mongodb://localhost:27017/')
db = client['shop']
orders_collection = db['orders']

@login_required
@require_http_methods(["GET"])
def search_orders(request):
    """
    Search orders by customer email or order ID.
    Supports MongoDB NoSQL queries via JSON body.
    """
    try:
        # Parse the JSON query body
        query_data = json.loads(request.body)
    except (json.JSONDecodeError, TypeError):
        return JsonResponse({'error': 'Invalid JSON'}, status=400)

    # Defensive: try to sanitize by replacing $ operators
    sanitized = {}
    for key, value in query_data.items():
        # Replace $ in keys to prevent operator injection
        clean_key = str(key).replace('$', '')
        sanitized[clean_key] = value

    # Build MongoDB query
    query = {}
    email = sanitized.get('email')
    order_id = sanitized.get('order_id')

    # Defensive: validate email format if present
    if email:
        try:
            validate_email(email)
            query['customer_email'] = email
        except ValidationError:
            # Fallback to regex search if email invalid
            query['customer_email'] = {'$regex': email}

    if order_id:
        query['order_id'] = order_id

    # Execute query
    results = list(orders_collection.find(query).limit(50))

    # Format results (strip ObjectId)
    formatted = []
    for doc in results:
        doc['_id'] = str(doc['_id'])
        formatted.append(doc)

    return JsonResponse({'orders': formatted}, safe=False)
